import json
import math
from pathlib import Path

# ১) ২x২ Near-collinear Matrix-এর নিখুঁত Eigenvalue দিয়ে Condition Number যাচাই
X_toy = [[1.0, 1.0], [1.0, 1.0001]]
g00 = X_toy[0][0] ** 2 + X_toy[1][0] ** 2
g01 = X_toy[0][0] * X_toy[0][1] + X_toy[1][0] * X_toy[1][1]
g11 = X_toy[0][1] ** 2 + X_toy[1][1] ** 2

def cond_2x2(a, b, d):
    tr = a + d
    det = a * d - b * b
    disc = math.sqrt(max(tr * tr - 4.0 * det, 0.0))
    lam_max = 0.5 * (tr + disc)
    lam_min = 0.5 * (tr - disc)
    return lam_max / lam_min

print("Near-collinear cond(lambda=0.0):", f"{cond_2x2(g00, g01, g11):.2e}")
print("Near-collinear cond(lambda=1.0):", round(cond_2x2(g00 + 1.0, g01, g11 + 1.0), 4))

# ২) বাস্তব MovieLens User 15-এর 9x9 Gram Matrix বানিয়ে lambda in [0.1, 1.0, 10.0]-এ SPD যাচাই
lab = json.loads(Path("assets/datasets/movielens/factor_lab.json").read_text(encoding="utf-8"))
q_all = lab["weights"]["explicit_als"]["q"]
item_lookup = {}
for idx in range(len(lab["items"])):
    item_lookup[lab["items"][idx]] = idx

rows = []
for mid in lab["als_audit"]["items"]:
    rows.append([1.0] + list(q_all[item_lookup[mid]]))

G9 = []
for r in range(9):
    G9.append([0.0] * 9)
for row in rows:
    for r in range(9):
        for c in range(9):
            G9[r][c] += row[r] * row[c]

for reg in [0.1, 1.0, 10.0]:
    A = []
    for r in range(9):
        A.append(list(G9[r]))
        A[r][r] += reg
    L = []
    for r in range(9):
        L.append([0.0] * 9)
    min_diag = 1e9
    for i in range(9):
        for j in range(i + 1):
            s = 0.0
            for k in range(j):
                s += L[i][k] * L[j][k]
            if i == j:
                val = math.sqrt(A[i][i] - s)
                L[i][j] = val
                if val < min_diag:
                    min_diag = val
            else:
                L[i][j] = (A[i][j] - s) / L[j][j]
    assert min_diag > 0.0
    print(f"User 15 (reg={reg:4.1f}): SPD=True | min Cholesky diag={min_diag:.4f} | A[0][0]={A[0][0]:.1f}")

import json
from pathlib import Path

# ১) হাতে-কলমে 3-Item উদাহরণে Dense বনাম Gram Trick যাচাই
Y_toy = [[1.0, 0.0], [0.0, 1.0], [1.0, 1.0]]
p_toy = [1.0, 0.0, 0.0]
c_toy = [3.0, 1.0, 1.0]

A_dense = [[1.0, 0.0], [0.0, 1.0]]
b_dense = [0.0, 0.0]
for i in range(3):
    for r in range(2):
        b_dense[r] += c_toy[i] * p_toy[i] * Y_toy[i][r]
        for col in range(2):
            A_dense[r][col] += c_toy[i] * Y_toy[i][r] * Y_toy[i][col]

A_gram = [[1.0, 0.0], [0.0, 1.0]]
for i in range(3):
    for r in range(2):
        for col in range(2):
            A_gram[r][col] += Y_toy[i][r] * Y_toy[i][col]
for r in range(2):
    for col in range(2):
        A_gram[r][col] += 2.0 * Y_toy[0][r] * Y_toy[0][col]
b_gram = [3.0 * Y_toy[0][0], 3.0 * Y_toy[0][1]]

det = A_gram[0][0] * A_gram[1][1] - A_gram[0][1] * A_gram[1][0]
x_toy = [
    (A_gram[1][1] * b_gram[0] - A_gram[0][1] * b_gram[1]) / det,
    (-A_gram[1][0] * b_gram[0] + A_gram[0][0] * b_gram[1]) / det,
]
assert A_dense == A_gram and b_dense == b_gram

# ২) বাস্তব MovieLens User 15-এর সব 7,867 আইটেমে Dense বনাম Gram Trick Parity যাচাই!
lab = json.loads(Path("assets/datasets/movielens/factor_lab.json").read_text(encoding="utf-8"))
base = json.loads(Path("assets/datasets/movielens/recommendation_lab.json").read_text(encoding="utf-8"))
user_id = lab["als_audit"]["user"]
item_idx = {}
for idx in range(len(lab["items"])):
    item_idx[lab["items"][idx]] = idx

liked = set()
for row in base["train"]:
    if row[0] == user_id and row[2] >= 4:
        liked.add(item_idx[row[1]])

Y = lab["weights"]["implicit_als"]["q"]
YtY = []
A_fast = []
A_full = []
for r in range(8):
    YtY.append([0.0] * 8)
    A_fast.append([0.0] * 8)
    A_full.append([0.0] * 8)

b_fast = [0.0] * 8
for i in range(len(Y)):
    yi = Y[i]
    c_i = 21.0 if i in liked else 1.0
    for r in range(8):
        if i in liked:
            b_fast[r] += 21.0 * yi[r]
        for col in range(8):
            prod = yi[r] * yi[col]
            YtY[r][col] += prod
            A_full[r][col] += c_i * prod

for r in range(8):
    for col in range(8):
        A_fast[r][col] = YtY[r][col]
        if r == col:
            A_full[r][col] += 0.1
            A_fast[r][col] += 0.1
for i in liked:
    yi = Y[i]
    for r in range(8):
        for col in range(8):
            A_fast[r][col] += 20.0 * yi[r] * yi[col]

max_mat_diff = 0.0
for r in range(8):
    for col in range(8):
        d = abs(A_fast[r][col] - A_full[r][col])
        if d > max_mat_diff:
            max_mat_diff = d

assert max_mat_diff < 1e-10
x_toy_r = [round(x_toy[0], 6), round(x_toy[1], 6)]
b_first3 = [round(b_fast[0], 4), round(b_fast[1], 4), round(b_fast[2], 4)]
print("Toy 3-item A:", A_gram, "| b:", b_gram)
print("Toy x_u (exact 9/14, -3/14):", x_toy_r)
print("User 15 liked positives:", len(liked), "out of", len(Y), "items")
print("Max |A_gram - A_dense| across 8x8:", f"{max_mat_diff:.2e}")
print("b_u first 3 entries:", b_first3)
